<div class="toolbar"><a class="back-link mb-0" href="<?= e(url('orders')) ?>">← Volver a pedidos</a><div class="toolbar-actions"><?php if(can_write()): ?><a class="btn btn-primary" href="<?= e(url('order-form',['id'=>$row['OrderID']])) ?>">Editar pedido</a><?php endif ?><?php if(is_admin()): ?><form method="post" action="<?= e(url('order-delete')) ?>" data-confirm="¿Eliminar el pedido y devolver sus unidades al inventario?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= e($row['OrderID']) ?>"><button class="btn btn-outline-danger">Eliminar</button></form><?php endif ?></div></div><section class="panel"><div class="panel-heading"><div><h2>Pedido #<?= e($row['OrderID']) ?></h2><p>Cliente <?= e($row['CustomerID']) ?> · <?= e($row['OrderDate']) ?></p></div><span class="soft-badge"><?= $row['ShippedDate']?'ENVIADO':'PENDIENTE' ?></span></div><dl class="row order-summary"><?php foreach(['ShipName'=>'Destinatario','ShipAddress'=>'Dirección','ShipCity'=>'Ciudad','ShipCountry'=>'País','RequiredDate'=>'Fecha requerida','ShippedDate'=>'Fecha de envío'] as $k=>$label): ?><div class="col-md-4"><dt><?= $label ?></dt><dd><?= e($row[$k]??'—') ?></dd></div><?php endforeach ?></dl><div class="table-responsive"><table class="table"><thead><tr><th>Producto</th><th>Cantidad</th><th>Precio</th><th>Descuento</th><th>Subtotal</th></tr></thead><tbody><?php $total=0;foreach($row['lines'] as $l):$subtotal=$l['UnitPrice']*$l['Quantity']*(1-$l['Discount']);$total+=$subtotal; ?><tr><td><?= e($l['ProductName']) ?></td><td><?= e($l['Quantity']) ?></td><td><?= money($l['UnitPrice']) ?></td><td><?= number_format($l['Discount']*100,2) ?> %</td><td><?= money($subtotal) ?></td></tr><?php endforeach ?></tbody></table></div><div class="order-total"><span>Venta neta <strong><?= money($total) ?></strong></span><span>Flete <strong><?= money($row['Freight']) ?></strong></span><span>Total <strong><?= money($total+$row['Freight']) ?></strong></span></div></section>
